content.css:
:root {
  --scv-primary: #3B82F6;
  --scv-primary-hover: #2563EB;
  --scv-bg-main: #FFFFFF;
  --scv-bg-side: #F9FAFB;
  --scv-bg-content: #F3F4F6;
  --scv-text-main: #1F2937;
  --scv-text-muted: #6B7280;
  --scv-border: #E5E7EB;
  --scv-html-border: black;
  --scv-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --scv-radius: 12px;
  --scv-font: 'Segoe UI', system-ui, -apple-system, sans-serif;
}
.scvtable-main-div {
  -webkit-touch-callout: none;
  -webkit-user-select: none;
  user-select: none;
  font-family: var(--scv-font);
  overflow: auto;
  width: 100%;
  height: 100%;
  position: relative;
  display: block;
}
.scvtable-main-div.menu-open {
  width: 50% !important;
}
.scvtable-settings-button {
  position: absolute;
  top: 0px;
  width: 30px;
  height: 30px;
  background-color: var(--scv-bg-main);
  border: 1px solid var(--scv-border);
  border-radius: 20%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 1000;
  box-shadow: var(--scv-shadow);
  transition: all 0.2s ease;
  color: var(--scv-text-muted);
}
.scvtable-settings-button:hover {
  background-color: var(--scv-bg-side);
  color: var(--scv-primary);
}
.scvtable-settings-button svg {
  width: 18px;
  height: 18px;
}
.scvtable-menu-popup {
  background-color: var(--scv-bg-main);
  display: none;
  z-index: 9999;
  overflow: hidden;
  font-family: var(--scv-font);
  user-select: none;
  border: 1px solid var(--scv-border);
}
.scvtable-menu-popup.docked-right {
  position: fixed;
  right: 0;
  top: 0;
  width: 50%;
  height: 100%;
  box-shadow: -4px 0 15px rgba(0, 0, 0, 0.1);
  border-left: 1px solid var(--scv-border);
  border-radius: 0;
}
.scvtable-menu-popup.floating {
  position: fixed;
  top: 0;
  left: 0;
  width: 600px;
  height: 450px;
  border-radius: var(--scv-radius);
  box-shadow: var(--scv-shadow);
  will-change: transform;
}
.scvtable-menu-header {
  background: linear-gradient(90deg, #2a71b8 0%, #3B82F6 100%);
  color: white;
  position: absolute;
  box-sizing: border-box;
  padding: 0 20px;
  width: 100%;
  height: 50px;
  line-height: 50px;
  left: 0px;
  top: 0;
  font-weight: 600;
  font-size: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.scvtable-menu-vertical-bar {
  background-color: var(--scv-bg-side);
  border-right: 1px solid var(--scv-border);
  position: absolute;
  width: 140px;
  top: 50px;
  bottom: 65px;
  left: 0;
}
.scvtable-menu-nav-item {
  padding: 12px 20px;
  color: var(--scv-text-main);
  font-weight: 500;
  font-size: 13px;
  transition: all 0.2s ease;
  cursor: pointer;
  border-left: 3px solid transparent;
}
.scvtable-menu-nav-item:hover {
  background-color: rgba(59, 130, 246, 0.05);
  color: var(--scv-primary);
}
.scvtable-menu-nav-item.active {
  background-color: rgba(59, 130, 246, 0.1);
  color: var(--scv-primary);
  border-left: 3px solid var(--scv-primary);
}
.scvtable-menu-content-container {
  background-color: var(--scv-bg-content);
  position: absolute;
  top: 50px;
  bottom: 65px;
  left: 140px;
  right: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 20px;
}
.scvtable-menu-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.scvtable-menu-section {
  background: var(--scv-bg-main);
  border: 1px solid var(--scv-border);
  border-radius: 10px;
  overflow: hidden;
  margin-bottom: 4px;
}
.scvtable-menu-content-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--scv-text-main);
  background: var(--scv-bg-side);
  padding: 12px 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--scv-border);
  margin: 0;
  transition: background 0.2s;
}
.scvtable-menu-content-title:hover {
  background: #f0f2f5;
}
.scvtable-menu-content-title-arrow {
  font-size: 10px;
  color: var(--scv-text-muted);
}
.scvtable-menu-content-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 5px;
  border-bottom: 1px solid var(--scv-border);
  transition: background 0.2s ease;
  flex-wrap: wrap;
  gap: 8px;
}
.scvtable-menu-content-item:last-child {
  border-bottom: none;
}
.scvtable-menu-content-item:hover {
  background: rgba(59, 130, 246, 0.02);
}
.scvtable-menu-content-list-label {
  font-size: 13px;
  color: var(--scv-text-main);
  flex: 1;
  min-width: 120px;
  word-break: break-word;
}
.scvtable-menu-content-list-input-color {
  border: 0;
  background-color: transparent;
}
.scvtable-menu-content-list-input,
.scvtable-menu-content-selector-input {
  padding: 6px 10px;
  border: 1px solid var(--scv-border);
  border-radius: 6px;
  font-size: 13px;
  outline: none;
  transition: border-color 0.2s;
  min-width: 100px;
  flex-shrink: 1;
  max-width: 100%;
}
.scvtable-menu-content-list-input:focus,
.scvtable-menu-content-selector-input:focus {
  border-color: var(--scv-primary);
}
.scvtable-btn {
  padding: 8px 16px;
  border-radius: 6px;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
  outline: none;
}
.scvtable-apply,
.scvtable-save {
  background-color: var(--scv-primary);
  color: white;
}
.scvtable-apply:hover,
.scvtable-save:hover {
  background-color: var(--scv-primary-hover);
  transform: translateY(-1px);
}
.scvtable-cancel {
  background-color: transparent;
  color: var(--scv-text-muted);
  border: 1px solid var(--scv-border);
}
.scvtable-cancel:hover {
  background-color: var(--scv-bg-side);
  color: var(--scv-text-main);
}
.scvtable-menu-footer {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 65px;
  background: var(--scv-bg-main);
  border-top: 1px solid var(--scv-border);
  display: flex;
  justify-content: flex-end;
  align-items: center;
  padding: 0 20px;
  box-sizing: border-box;
  gap: 12px;
}
.scvtable-prop-button {
  position: absolute;
  left: 0px;
  top: 50px;
  width: 12px;
  height: 40px;
  background-color: #d3d3d3;
  border-radius: 0px 5px 5px 0px;
  z-index: 100;
}
