/* Button prototype */
:root {
  --colour-black: #1e1e1e;
  --colour-white: #ffffff;
}
button,
.button {
  --button: hsl(0, 0%, 80%);
  --button-hover: hsl(0, 0%, 100%);
  --button-active: hsl(0, 0%, 70%);
  --button-visited: hsl(0, 0%, 20%);
  --button-colour: var(--colour-white);
  --button-border: var(--colour-black);
}
button:active {
  background: var(--button-active);
}
button:visited {
  background: var(--button-visited);
}
/* Tooltip */
.scvtable-info {
  position: absolute;
  padding: 5px;
  box-sizing: border-box;
  width: 60px;
  background-color: #e1e1e1;
  z-index: 9999;
  border-radius: 5px 5px 5px 5px;
  pointer-events: none;
}
/* Modern Popup System */
.scvtable-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(2px);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
}
.scvtable-popup-modern {
  background: var(--scv-bg-main);
  border-radius: var(--scv-radius);
  box-shadow: var(--scv-shadow);
  width: 700px;
  max-width: 90vw;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: scv-fade-in 0.2s ease-out;
}
@keyframes scv-fade-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.scvtable-popup-modern-header {
  padding: 15px 20px;
  background: var(--scv-bg-side);
  border-bottom: 1px solid var(--scv-border);
  font-weight: 600;
  color: var(--scv-text-main);
}
.scvtable-popup-modern-content {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 15px;
}
.scvtable-popup-modern-footer {
  padding: 15px 20px;
  background: var(--scv-bg-side);
  border-top: 1px solid var(--scv-border);
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}
.scvtable-popup-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: 15px;
}
.scvtable-popup-field {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.scvtable-popup-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--scv-text-muted);
}
/* HTML Table Styling */
#htmlTableDiv {
  width: 100%;
  height: 100%;
  overflow: auto;
  font-family: var(--scv-font);
}
#htmlTableDiv .scv-html-table {
  border-collapse: collapse;
  color: var(--scv-text-main);
  font-size: 13px;
  text-align: left;
  background: var(--scv-bg-main);
  user-select: text;
  /* Allow text selection for copying */
}
#htmlTableDiv .scv-html-table thead {
  top: 0;
  z-index: 10;
}
#htmlTableDiv .scv-html-table thead tr th {
  color: var(--scv-text-main);
  text-transform: none;
  border-bottom: 1px solid var(--scv-html-border);
  white-space: pre-wrap;
  word-wrap: break-word;
  padding: 4px 8px;
  line-height: 1.2;
  font-family: Arial, sans-serif;
  font-weight: normal;
  text-align: center;
  font-size: 8pt;
  min-height: 24px;
  height: auto;
  vertical-align: middle;
}
#htmlTableDiv .scv-html-table thead tr th.scv-cut-text {
  white-space: nowrap !important;
  height: 24px !important;
}
#htmlTableDiv .scv-html-table thead tr th.scv-cut-text .scv-header-content {
  overflow: hidden;
}
#htmlTableDiv .scv-html-table thead tr th.scv-cut-text .scv-header-content span:first-child {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: block;
}
#htmlTableDiv .scv-html-table thead tr th .scv-header-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 100%;
}
#htmlTableDiv .scv-html-table thead tr th .scv-header-content .scv-sort-icon {
  font-size: 14px;
  opacity: 0.3;
  transition: opacity 0.2s, color 0.2s;
  user-select: none;
}
#htmlTableDiv .scv-html-table thead tr th .scv-header-content .scv-sort-icon.active {
  opacity: 1;
  color: var(--scv-primary);
}
#htmlTableDiv .scv-html-table thead tr th:hover .scv-sort-icon {
  opacity: 0.6;
}
#htmlTableDiv .scv-html-table tbody tr {
  transition: background-color 0.2s ease;
}
#htmlTableDiv .scv-html-table tbody tr:hover {
  background-color: rgba(59, 130, 246, 0.04);
}
#htmlTableDiv .scv-html-table tbody tr td {
  border-bottom: 1px solid var(--scv-html-border);
  height: 21px;
  vertical-align: middle;
  white-space: nowrap;
  cursor: pointer;
  /* Indicate clickability for copy */
}
#htmlTableDiv .scv-html-table tbody tr td:active {
  background-color: rgba(59, 130, 246, 0.1);
}
.scv-copy-feedback {
  position: fixed;
  background: rgba(0, 0, 0, 0.8);
  color: white;
  padding: 6px 12px;
  border-radius: 4px;
  font-size: 12px;
  z-index: 10001;
  pointer-events: none;
  animation: scv-fade-out 1s forwards;
}
@keyframes scv-fade-out {
  0% {
    opacity: 1;
    transform: translateY(0);
  }
  70% {
    opacity: 1;
    transform: translateY(-5px);
  }
