}
.scvtable-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}
.scvtable-slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #ccc;
  transition: 0.2s;
  border-radius: 20px;
}
.scvtable-slider:before {
  position: absolute;
  content: "";
  height: 14px;
  width: 14px;
  left: 3px;
  bottom: 3px;
  background-color: white;
  transition: 0.2s;
  border-radius: 50%;
}
input:checked + .scvtable-slider {
  background-color: var(--scv-primary);
}
input:checked + .scvtable-slider:before {
  transform: translateX(16px);
}
